-- LAT Part I Urdu: original MCQs on word meanings, synonyms and antonyms, idioms and proverbs, grammar, and poets and writers.

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Urdu', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('URD-0001', 'Word meanings', 'Meanings', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Urdu Lughat (Urdu Dictionary Board)', '«مسرت» کا مطلب ہے:', '["حیرت", "خوشی", "شرمندگی", "غم"]', 1, '«مسرت» is an Arabic word for joy or happiness, the same as «خوشی».', '{"0": "«حیرت» means surprise.", "2": "«شرمندگی» means shame, which is «ندامت».", "3": "«غم» means sorrow, the opposite of «مسرت»."}'),
  ('URD-0002', 'Word meanings', 'Meanings', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Urdu Lughat (Urdu Dictionary Board)', '«ندامت» کا مطلب ہے:', '["غصہ", "بہادری", "دشمنی", "شرمندگی"]', 3, '«ندامت» means regret or shame for something one has done, the same as «شرمندگی».', '{"0": "«غصہ» means anger.", "1": "«بہادری» means bravery, which is «شجاعت».", "2": "«دشمنی» means enmity, which is «عداوت»."}'),
  ('URD-0003', 'Word meanings', 'Meanings', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Urdu Lughat (Urdu Dictionary Board)', '«تشنگی» کا مطلب ہے:', '["تھکن", "بھوک", "نیند", "پیاس"]', 3, '«تشنگی» comes from Persian «تشنہ» (thirsty) and means thirst, «پیاس».', '{"0": "Tiredness is «تھکن» or «ماندگی».", "1": "Hunger is «گرسنگی» or «بھوک», not «تشنگی».", "2": "Sleep is «نیند» or «خواب»."}'),
  ('URD-0004', 'Word meanings', 'Meanings', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Urdu Lughat (Urdu Dictionary Board)', '«قفس» کا مطلب ہے:', '["باغ", "قید خانہ", "پنجرہ", "گھونسلا"]', 2, '«قفس» is a cage, «پنجرہ», a favourite image of the caged bird in Urdu poetry.', '{"0": "A garden is «گلشن» or «چمن».", "1": "A prison is «زنداں» or «قید خانہ»; «قفس» is specifically a bird''s cage.", "3": "A nest is «آشیانہ» or «گھونسلا»."}'),
  ('URD-0005', 'Word meanings', 'Meanings', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Urdu Lughat (Urdu Dictionary Board)', '«اجل» کا مطلب ہے:', '["قسمت", "بیماری", "موت", "زندگی"]', 2, '«اجل» means the appointed hour of death, «موت».', '{"0": "Fate is «تقدیر» or «قسمت».", "1": "Illness is «مرض» or «بیماری».", "3": "Life is «زیست» or «حیات», the opposite of «اجل»."}'),
  ('URD-0006', 'Word meanings', 'Meanings', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Urdu Lughat (Urdu Dictionary Board)', '«زیست» کا مطلب ہے:', '["موت", "عبادت", "زندگی", "خوشبو"]', 2, '«زیست» is a Persian word for life, «زندگی».', '{"0": "Death is «اجل» or «موت».", "1": "Worship is «عبادت» or «بندگی».", "3": "Fragrance is «خوشبو» or «مہک»."}'),
  ('URD-0007', 'Word meanings', 'Meanings', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Urdu Lughat (Urdu Dictionary Board)', '«تیرگی» کا مطلب ہے:', '["تیزی", "اندھیرا", "روشنی", "تیر اندازی"]', 1, '«تیرگی» comes from Persian «تیرہ» (dark) and means darkness, «اندھیرا».', '{"0": "Speed is «تیزی»; «تیرگی» has nothing to do with «تیز».", "2": "Light is «روشنی» or «نور», the opposite.", "3": "Archery is «تیر اندازی»; «تیرگی» comes from «تیرہ» (dark), not «تیر» (arrow)."}'),
  ('URD-0008', 'Word meanings', 'Meanings', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Urdu Lughat (Urdu Dictionary Board)', '«مژگاں» کا مطلب ہے:', '["آنسو", "بھنویں", "ہونٹ", "پلکیں"]', 3, '«مژگاں» is the plural of «مژہ», an eyelash, so it means «پلکیں».', '{"0": "Tears are «اشک» or «آنسو».", "1": "Eyebrows are «ابرو».", "2": "Lips are «لب»."}'),
  ('URD-0009', 'Word meanings', 'Meanings', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Urdu Lughat (Urdu Dictionary Board)', '«صبا» کا مطلب ہے:', '["تیز آندھی", "صبح کی ٹھنڈی ہوا", "بارش", "شام کا وقت"]', 1, '«صبا» is the soft cool breeze of early morning, often a messenger in Urdu poetry.', '{"0": "A storm is «آندھی» or «طوفان».", "2": "Rain is «باراں» or «بارش».", "3": "Evening is «شام» or «مساء»."}'),
  ('URD-0010', 'Word meanings', 'Meanings', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Urdu Lughat (Urdu Dictionary Board)', '«عدو» کا مطلب ہے:', '["دشمن", "دوست", "مہمان", "پڑوسی"]', 0, '«عدو» is an Arabic word for enemy, «دشمن».', '{"1": "A friend is «دوست» or «یار», the opposite of «عدو».", "2": "A guest is «مہمان».", "3": "A neighbour is «ہمسایہ» or «پڑوسی»."}'),
  ('URD-0011', 'Word meanings', 'Meanings', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Urdu Lughat (Urdu Dictionary Board)', '«قناعت» کا مطلب ہے:', '["لالچ کرنا", "دوسروں کی مدد کرنا", "سخت محنت کرنا", "جو مل جائے اس پر راضی رہنا"]', 3, '«قناعت» means contentment: being satisfied with what one has.', '{"0": "Greed is «حرص» or «لالچ», the opposite of «قناعت».", "1": "Helping others is «امداد» or «خدمت».", "2": "Hard work is «محنت» or «مشقت»."}'),
  ('URD-0012', 'Word meanings', 'Meanings', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Urdu Lughat (Urdu Dictionary Board)', '«شجاعت» کا مطلب ہے:', '["ذہانت", "بہادری", "سخاوت", "عاجزی"]', 1, '«شجاعت» means courage or bravery, «بہادری».', '{"0": "«ذہانت» means intelligence.", "2": "«سخاوت» means generosity.", "3": "«عاجزی» means humility."}'),
  ('URD-0013', 'Word meanings', 'Meanings', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Urdu Lughat (Urdu Dictionary Board)', '«سخاوت» کا مطلب ہے:', '["سچائی", "بہادری", "فیاضی", "کنجوسی"]', 2, '«سخاوت» means generosity, «فیاضی».', '{"0": "Truthfulness is «صداقت».", "1": "Bravery is «شجاعت».", "3": "Miserliness is «بخل» or «کنجوسی», the opposite."}'),
  ('URD-0014', 'Word meanings', 'Literary words', 'hard', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Urdu Lughat (Urdu Dictionary Board)', '«عنقا» کا مطلب ہے:', '["بہت بڑا", "نایاب", "بہت پرانا", "بہت عام"]', 1, '«عنقا» is a legendary bird that no one has seen, so «عنقا ہونا» means to be very rare or to vanish: «نایاب».', '{"0": "Huge is «عظیم» or «بہت بڑا».", "2": "Very old is «قدیم».", "3": "«عنقا» means the opposite: something that is almost never found."}'),
  ('URD-0015', 'Word meanings', 'Literary words', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Urdu Lughat (Urdu Dictionary Board)', '«گریہ» کا مطلب ہے:', '["رونا", "ہنسنا", "گرنا", "چیخنا"]', 0, '«گریہ» means weeping, «رونا»; «گریہ و زاری» is weeping and wailing.', '{"1": "Laughing is «خندہ».", "2": "Falling is «گرنا»; «گریہ» is not from it.", "3": "Shouting is «فریاد» or «چیخنا»."}'),
  ('URD-0016', 'Word meanings', 'Meanings', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Urdu Lughat (Urdu Dictionary Board)', '«مسافت» کا مطلب ہے:', '["منزل", "سفر کا سامان", "فاصلہ", "مسافر"]', 2, '«مسافت» means distance or the length of a journey, «فاصلہ».', '{"0": "«منزل» is the destination.", "1": "Luggage for a journey is «زادِ راہ» or «سامانِ سفر».", "3": "«مسافر» is the traveller, not the distance."}'),
  ('URD-0017', 'Word meanings', 'Meanings', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Urdu Lughat (Urdu Dictionary Board)', '«دہن» کا مطلب ہے:', '["منہ", "ناک", "گردن", "دانت"]', 0, '«دہن» (Persian) means the mouth, «منہ».', '{"1": "The nose is «بینی».", "2": "The neck is «گردن».", "3": "Teeth are «دنداں»."}'),
  ('URD-0018', 'Word meanings', 'Meanings', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Urdu Lughat (Urdu Dictionary Board)', '«ہمسایہ» کا مطلب ہے:', '["دشمن", "رشتہ دار", "مسافر", "پڑوسی"]', 3, '«ہمسایہ» means one who lives in the next house, «پڑوسی».', '{"0": "An enemy is «عدو» or «دشمن».", "1": "A relative is «عزیز» or «رشتہ دار».", "2": "A traveller is «مسافر» or «راہی»."}'),
  ('URD-0019', 'Word meanings', 'Meanings', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Urdu Lughat (Urdu Dictionary Board)', '«گلشن» کا مطلب ہے:', '["باغ", "پھول", "جنگل", "صحرا"]', 0, '«گلشن» is a garden of flowers, «باغ».', '{"1": "A flower is «گل»; «گلشن» is the place where flowers grow.", "2": "A forest is «جنگل» or «بن».", "3": "A desert is «صحرا» or «ریگستان»."}'),
  ('URD-0020', 'Word meanings', 'Meanings', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Urdu Lughat (Urdu Dictionary Board)', '«خار» کا مطلب ہے:', '["پتا", "پھول", "شاخ", "کانٹا"]', 3, '«خار» is a thorn, «کانٹا».', '{"0": "A leaf is «برگ».", "1": "A flower is «گل»; «گل و خار» means flower and thorn.", "2": "A branch is «شاخ»."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Urdu', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('URD-0021', 'Word meanings', 'Meanings', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Urdu Lughat (Urdu Dictionary Board)', '«سِحر» (س کے نیچے زیر) کا مطلب ہے:', '["دعا", "جادو", "نیند", "صبح"]', 1, '«سِحر» (sihr) means magic, «جادو»; «سَحَر» (sahar) means dawn. The vowel marks change the meaning.', '{"0": "A prayer is «دعا».", "2": "Sleep is «خواب» or «نیند».", "3": "Dawn is «سَحَر», with zabar on both letters; the zer changes the word."}'),
  ('URD-0022', 'Synonyms and antonyms', 'Synonyms', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Urdu Lughat (Urdu Dictionary Board)', '«آفتاب» کا مترادف کیا ہے؟', '["ستارہ", "سورج", "چاند", "آسمان"]', 1, '«آفتاب» (Persian) and «سورج» both mean the sun.', '{"0": "A star is «اختر» or «ستارہ».", "2": "The moon is «مہتاب» or «ماہ».", "3": "The sky is «فلک» or «آسمان»."}'),
  ('URD-0023', 'Synonyms and antonyms', 'Synonyms', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Urdu Lughat (Urdu Dictionary Board)', '«مہتاب» کا مترادف کیا ہے؟', '["سورج", "چاند", "روشنی", "بادل"]', 1, '«مہتاب» (Persian) and «چاند» both mean the moon.', '{"0": "The sun is «آفتاب».", "2": "Light is «نور» or «روشنی».", "3": "A cloud is «ابر»."}'),
  ('URD-0024', 'Synonyms and antonyms', 'Synonyms', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Urdu Lughat (Urdu Dictionary Board)', '«فلک» کا مترادف کیا ہے؟', '["زمین", "پہاڑ", "آسمان", "سمندر"]', 2, '«فلک» and «آسمان» both mean the sky.', '{"0": "The earth is «ارض» or «زمین».", "1": "A mountain is «کوہ».", "3": "The sea is «بحر» or «سمندر»."}'),
  ('URD-0025', 'Synonyms and antonyms', 'Synonyms', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Urdu Lughat (Urdu Dictionary Board)', '«بحر» کا مترادف کیا ہے؟', '["سمندر", "کنواں", "دریا", "بادل"]', 0, '«بحر» is an Arabic word for the sea, «سمندر»; «بحرِ ہند» is the Indian Ocean.', '{"1": "A well is «چاہ» or «کنواں».", "2": "A river is «نہر» or «دریا»; «بحر» is the sea.", "3": "A cloud is «ابر»."}'),
  ('URD-0026', 'Synonyms and antonyms', 'Synonyms', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Urdu Lughat (Urdu Dictionary Board)', '«کوہ» کا مترادف کیا ہے؟', '["پہاڑ", "دریا", "وادی", "جنگل"]', 0, '«کوہ» (Persian) means a mountain, «پہاڑ»; «کوہِ ہمالیہ» is the Himalaya.', '{"1": "A river is «دریا».", "2": "A valley is «وادی».", "3": "A forest is «جنگل»."}'),
  ('URD-0027', 'Synonyms and antonyms', 'Synonyms', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Urdu Lughat (Urdu Dictionary Board)', '«آتش» کا مترادف کیا ہے؟', '["ہوا", "پانی", "مٹی", "آگ"]', 3, '«آتش» (Persian) means fire, «آگ».', '{"0": "Air is «باد» or «ہوا».", "1": "Water is «آب».", "2": "Earth or clay is «خاک»."}'),
  ('URD-0028', 'Synonyms and antonyms', 'Synonyms', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Urdu Lughat (Urdu Dictionary Board)', '«چشم» کا مترادف کیا ہے؟', '["پاؤں", "ہاتھ", "آنکھ", "کان"]', 2, '«چشم» (Persian) means the eye, «آنکھ».', '{"0": "The foot is «پا».", "1": "The hand is «دست».", "3": "The ear is «گوش»."}'),
  ('URD-0029', 'Synonyms and antonyms', 'Synonyms', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Urdu Lughat (Urdu Dictionary Board)', '«شب» کا مترادف کیا ہے؟', '["شام", "رات", "دن", "صبح"]', 1, '«شب» (Persian) means night, «رات»; «شبِ برات» is a night of the Islamic calendar.', '{"0": "Evening is «شام».", "2": "Day is «روز».", "3": "Morning is «سحر» or «صبح»."}'),
  ('URD-0030', 'Synonyms and antonyms', 'Synonyms', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Urdu Lughat (Urdu Dictionary Board)', '«قلب» کا مترادف کیا ہے؟', '["دماغ", "دل", "سینہ", "جگر"]', 1, '«قلب» (Arabic) means the heart, «دل».', '{"0": "The brain is «دماغ».", "2": "The chest is «سینہ».", "3": "The liver is «جگر»."}'),
  ('URD-0031', 'Synonyms and antonyms', 'Synonyms', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Urdu Lughat (Urdu Dictionary Board)', '«عداوت» کا مترادف کیا ہے؟', '["دوستی", "عبادت", "دشمنی", "عادت"]', 2, '«عداوت» means enmity, «دشمنی»; it comes from the same root as «عدو» (enemy).', '{"0": "Friendship is «دوستی», the opposite.", "1": "«عبادت» means worship; it sounds similar but is a different word.", "3": "«عادت» means habit."}'),
  ('URD-0032', 'Synonyms and antonyms', 'Antonyms', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Urdu Lughat (Urdu Dictionary Board)', '«عروج» کا متضاد کیا ہے؟', '["زوال", "بلندی", "ترقی", "کمال"]', 0, '«عروج» means rise and «زوال» means decline; they are a standard pair of opposites.', '{"1": "«بلندی» (height) is close to «عروج» in meaning.", "2": "«ترقی» (progress) is close to «عروج» in meaning, not its opposite.", "3": "«کمال» (perfection) is not the opposite."}'),
  ('URD-0033', 'Synonyms and antonyms', 'Antonyms', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Urdu Lughat (Urdu Dictionary Board)', '«آغاز» کا متضاد کیا ہے؟', '["ابتدا", "آمد", "انجام", "شروع"]', 2, '«آغاز» is the beginning and «انجام» is the end.', '{"0": "«ابتدا» means beginning, the same as «آغاز».", "1": "«آمد» means arrival.", "3": "«شروع» means beginning, the same as «آغاز»."}'),
  ('URD-0034', 'Synonyms and antonyms', 'Antonyms', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Urdu Lughat (Urdu Dictionary Board)', '«فتح» کا متضاد کیا ہے؟', '["فاتح", "کامیابی", "شکست", "جنگ"]', 2, '«فتح» means victory and «شکست» means defeat.', '{"0": "«فاتح» is the victor, from the same root.", "1": "«کامیابی» (success) is close to «فتح» in meaning.", "3": "«جنگ» is the war itself, not the opposite of victory."}'),
  ('URD-0035', 'Synonyms and antonyms', 'Antonyms', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Urdu Lughat (Urdu Dictionary Board)', '«حاضر» کا متضاد کیا ہے؟', '["موجود", "ظاہر", "غائب", "حاضری"]', 2, '«حاضر» means present and «غائب» means absent.', '{"0": "«موجود» means present, the same as «حاضر».", "1": "«ظاہر» means apparent; its opposite is «باطن».", "3": "«حاضری» is attendance, from the same root."}'),
  ('URD-0036', 'Synonyms and antonyms', 'Antonyms', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Urdu Lughat (Urdu Dictionary Board)', '«عزت» کا متضاد کیا ہے؟', '["دولت", "شہرت", "عظمت", "ذلت"]', 3, '«عزت» means honour and «ذلت» means disgrace.', '{"0": "«دولت» means wealth.", "1": "«شہرت» means fame.", "2": "«عظمت» means greatness, close to «عزت»."}'),
  ('URD-0037', 'Synonyms and antonyms', 'Antonyms', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Urdu Lughat (Urdu Dictionary Board)', '«ظاہر» کا متضاد کیا ہے؟', '["واضح", "ظالم", "باطن", "غائب"]', 2, '«ظاہر» means outward or visible and «باطن» means inward or hidden.', '{"0": "«واضح» means clear, close to «ظاہر».", "1": "«ظالم» means cruel; it only looks similar.", "3": "«غائب» is the opposite of «حاضر»."}'),
  ('URD-0038', 'Synonyms and antonyms', 'Antonyms', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Urdu Lughat (Urdu Dictionary Board)', '«قدیم» کا متضاد کیا ہے؟', '["مشہور", "پرانا", "تاریخی", "جدید"]', 3, '«قدیم» means ancient or old and «جدید» means new or modern.', '{"0": "«مشہور» means famous.", "1": "«پرانا» means old, the same as «قدیم».", "2": "«تاریخی» means historical."}'),
  ('URD-0039', 'Synonyms and antonyms', 'Antonyms', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Urdu Lughat (Urdu Dictionary Board)', '«ارزاں» کا متضاد کیا ہے؟', '["سستا", "آسان", "گراں", "کم"]', 2, '«ارزاں» means cheap and «گراں» means dear or expensive; «گرانی» is high prices.', '{"0": "«سستا» means cheap, the same as «ارزاں».", "1": "«آسان» means easy; its opposite is «مشکل».", "3": "«کم» means less; its opposite is «زیادہ»."}'),
  ('URD-0040', 'Synonyms and antonyms', 'Antonyms', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Urdu Lughat (Urdu Dictionary Board)', '«سخی» کا متضاد کیا ہے؟', '["غریب", "بہادر", "فیاض", "بخیل"]', 3, '«سخی» means generous and «بخیل» means miserly.', '{"0": "«غریب» means poor; its opposite is «امیر».", "1": "«بہادر» means brave; its opposite is «بزدل».", "2": "«فیاض» means generous, the same as «سخی»."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Urdu', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('URD-0041', 'Synonyms and antonyms', 'Antonyms', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Urdu Lughat (Urdu Dictionary Board)', '«وفا» کا متضاد کیا ہے؟', '["جفا", "صفا", "دعا", "وفادار"]', 0, '«وفا» means faithfulness and «جفا» means cruelty or unfaithfulness; «وفا و جفا» is a common pair in ghazal.', '{"1": "«صفا» means purity; it only rhymes with «وفا».", "2": "«دعا» means prayer.", "3": "«وفادار» is a faithful person, from the same word."}'),
  ('URD-0042', 'Synonyms and antonyms', 'Antonyms', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Urdu Lughat (Urdu Dictionary Board)', '«فانی» کا متضاد کیا ہے؟', '["مردہ", "باقی", "فن", "فنا"]', 1, '«فانی» means mortal or perishable and «باقی» means lasting; the Quran says «کُلُّ مَنْ عَلَیْہَا فَانٍ» and only the Lord remains.', '{"0": "«مردہ» means dead, which is not the opposite of «فانی».", "2": "«فن» means art or skill.", "3": "«فنا» (passing away) is the noun of «فانی», not its opposite."}'),
  ('URD-0043', 'Synonyms and antonyms', 'Antonyms', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Urdu Lughat (Urdu Dictionary Board)', '«اقرار» کا متضاد کیا ہے؟', '["انکار", "وعدہ", "اعتراف", "اصرار"]', 0, '«اقرار» means to admit or agree and «انکار» means to refuse or deny.', '{"1": "«وعدہ» means promise.", "2": "«اعتراف» (admission) is close to «اقرار».", "3": "«اصرار» means insistence; it only sounds similar."}'),
  ('URD-0044', 'Synonyms and antonyms', 'Antonyms', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Urdu Lughat (Urdu Dictionary Board)', '«آباد» کا متضاد کیا ہے؟', '["بستی", "ویران", "شہر", "خوشحال"]', 1, '«آباد» means inhabited and «ویران» means deserted.', '{"0": "«بستی» is a settlement, which is «آباد».", "2": "«شہر» is a city.", "3": "«خوشحال» means prosperous."}'),
  ('URD-0045', 'Synonyms and antonyms', 'Antonyms', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Urdu Lughat (Urdu Dictionary Board)', '«عالم» (ل کے نیچے زیر، یعنی پڑھا لکھا) کا متضاد کیا ہے؟', '["فاضل", "جاہل", "طالب علم", "دنیا"]', 1, '«عالِم» means a learned person and «جاہل» means an ignorant one.', '{"0": "«فاضل» means learned, close to «عالِم».", "2": "«طالب علم» is a student, not the opposite.", "3": "«دنیا» is the meaning of «عالَم» with zabar, a different word."}'),
  ('URD-0046', 'Synonyms and antonyms', 'Antonyms', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Urdu Lughat (Urdu Dictionary Board)', '«نفع» کا متضاد کیا ہے؟', '["فائدہ", "نقصان", "تجارت", "قرض"]', 1, '«نفع» means profit and «نقصان» means loss.', '{"0": "«فائدہ» means profit, the same as «نفع».", "2": "«تجارت» means trade.", "3": "«قرض» means a loan."}'),
  ('URD-0047', 'Idioms and proverbs', 'Idioms', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Farhang-e-Asifiya (idioms and proverbs)', 'محاورہ «آنکھوں کا تارا» کا مطلب ہے:', '["بہت چالاک", "نظر کمزور ہونا", "دور رہنے والا", "بہت پیارا"]', 3, '«آنکھوں کا تارا» is someone very dear, usually a child to parents.', '{"0": "Clever is «چالاک» or «ہوشیار»; the idiom is about love.", "1": "The idiom is not literal; it is about a beloved person.", "2": "Someone rarely seen is «عید کا چاند»."}'),
  ('URD-0048', 'Idioms and proverbs', 'Idioms', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Farhang-e-Asifiya (idioms and proverbs)', 'محاورہ «ایڑی چوٹی کا زور لگانا» کا مطلب ہے:', '["زخمی ہونا", "تیز دوڑنا", "بال سنوارنا", "پوری کوشش کرنا"]', 3, '«ایڑی چوٹی کا زور لگانا» means to try with all one''s strength, from heel to head.', '{"0": "The idiom is not about injury.", "1": "Running very fast is «ہوا سے باتیں کرنا».", "2": "«چوٹی» here means the top of the head, not a braid to dress."}'),
  ('URD-0049', 'Idioms and proverbs', 'Idioms', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Farhang-e-Asifiya (idioms and proverbs)', 'محاورہ «آستین کا سانپ» کس کے لیے بولا جاتا ہے؟', '["بہت بہادر آدمی", "بہت کنجوس آدمی", "جادوگر", "دوست کے روپ میں دشمن"]', 3, '«آستین کا سانپ» is a snake hidden in one''s own sleeve: an enemy who poses as a friend.', '{"0": "A brave man is called «شیر دل».", "1": "A miser is «مکھی چوس».", "2": "A magician is «ساحر» or «جادوگر»."}'),
  ('URD-0050', 'Idioms and proverbs', 'Idioms', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Farhang-e-Asifiya (idioms and proverbs)', 'محاورہ «ہوا سے باتیں کرنا» کا مطلب ہے:', '["بہت تیز دوڑنا", "ہوائی جہاز چلانا", "فضول باتیں کرنا", "اکیلے میں بڑبڑانا"]', 0, '«ہوا سے باتیں کرنا» means to go as fast as the wind, as in «گھوڑا ہوا سے باتیں کرنے لگا».', '{"1": "The idiom is not literal.", "2": "Idle talk is «ہوائی باتیں» or «گپ ہانکنا».", "3": "Talking to oneself is not the meaning."}'),
  ('URD-0051', 'Idioms and proverbs', 'Idioms', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Farhang-e-Asifiya (idioms and proverbs)', 'محاورہ «دانت کھٹے کرنا» کا مطلب ہے:', '["بری طرح ہرانا", "بہت لالچ کرنا", "کھٹی چیز کھانا", "بہت ہنسنا"]', 0, '«دانت کھٹے کرنا» means to defeat someone thoroughly, as in «فوج نے دشمن کے دانت کھٹے کر دیے».', '{"1": "Greed is «منہ میں پانی بھر آنا».", "2": "The idiom is not literal.", "3": "Laughing a lot is «پیٹ میں بل پڑنا»."}'),
  ('URD-0052', 'Idioms and proverbs', 'Idioms', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Farhang-e-Asifiya (idioms and proverbs)', 'محاورہ «ناک میں دم کرنا» کا مطلب ہے:', '["بہت تنگ کرنا", "غرور کرنا", "عزت بچانا", "زکام ہونا"]', 0, '«ناک میں دم کرنا» means to harass someone until they can bear no more.', '{"1": "Pride is «ناک اونچی رکھنا».", "2": "Saving face is «ناک رکھ لینا».", "3": "The idiom is not about a cold."}'),
  ('URD-0053', 'Idioms and proverbs', 'Idioms', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Farhang-e-Asifiya (idioms and proverbs)', 'محاورہ «آگ بگولا ہونا» کا مطلب ہے:', '["سخت غصے میں آنا", "بہت خوش ہونا", "آگ لگ جانا", "بہت ڈر جانا"]', 0, '«آگ بگولا ہونا» means to flare up in great anger.', '{"1": "Great joy is «باغ باغ ہونا».", "2": "The idiom is not literal.", "3": "Great fear is «ہاتھ پاؤں پھول جانا»."}'),
  ('URD-0054', 'Idioms and proverbs', 'Idioms', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Farhang-e-Asifiya (idioms and proverbs)', 'محاورہ «ہاتھ پاؤں پھول جانا» کا مطلب ہے:', '["چوٹ لگنا", "موٹا ہو جانا", "گھبرا جانا", "سخت محنت کرنا"]', 2, '«ہاتھ پاؤں پھول جانا» means to panic and be unable to act.', '{"0": "The idiom is not about injury.", "1": "The idiom is not about weight.", "3": "Hard work is «خون پسینہ ایک کرنا»."}'),
  ('URD-0055', 'Idioms and proverbs', 'Idioms', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Farhang-e-Asifiya (idioms and proverbs)', 'محاورہ «طوطے کی طرح آنکھیں پھیرنا» کا مطلب ہے:', '["رٹا لگانا", "بے وفائی کرنا", "غور سے دیکھنا", "بہت بولنا"]', 1, 'A parrot turns away from the one who fed it, so the idiom means to turn faithless.', '{"0": "Learning by rote is «طوطے کی طرح رٹنا».", "2": "Looking closely is the opposite of turning the eyes away.", "3": "Talking too much is not the meaning."}'),
  ('URD-0056', 'Idioms and proverbs', 'Idioms', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Farhang-e-Asifiya (idioms and proverbs)', 'محاورہ «گھی کے چراغ جلانا» کا مطلب ہے:', '["اندھیرا دور کرنا", "خوشیاں منانا", "عبادت کرنا", "فضول خرچی کرنا"]', 1, 'Lighting lamps with ghee was a sign of great celebration, so the idiom means to rejoice.', '{"0": "The idiom is not literal.", "2": "The idiom is not about worship.", "3": "Waste is «پیسہ پانی کی طرح بہانا»."}'),
  ('URD-0057', 'Idioms and proverbs', 'Idioms', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Farhang-e-Asifiya (idioms and proverbs)', 'محاورہ «چکنا گھڑا» کس کے لیے بولا جاتا ہے؟', '["بہت باتونی آدمی", "بہت امیر آدمی", "جس پر کسی بات کا اثر نہ ہو", "بہت خوبصورت آدمی"]', 2, 'Water runs off an oiled pot, so «چکنا گھڑا» is a shameless person on whom advice has no effect.', '{"0": "A talker is «باتونی».", "1": "A rich man is «مالدار».", "3": "The idiom is not praise."}'),
  ('URD-0058', 'Idioms and proverbs', 'Idioms', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Farhang-e-Asifiya (idioms and proverbs)', 'محاورہ «اونٹ کے منہ میں زیرہ» کا مطلب ہے:', '["بے موقع بات", "بہت زیادہ", "بے ذائقہ کھانا", "ضرورت سے بہت کم"]', 3, 'A cumin seed in a camel''s mouth: something far too small for the need.', '{"0": "An untimely remark is not the meaning.", "1": "It means the opposite: far too little.", "2": "The idiom is not literal."}'),
  ('URD-0059', 'Idioms and proverbs', 'Idioms', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Farhang-e-Asifiya (idioms and proverbs)', 'محاورہ «نو دو گیارہ ہونا» کا مطلب ہے:', '["حساب کرنا", "بھاگ جانا", "مل جل کر رہنا", "دھوکا دینا"]', 1, '«نو دو گیارہ ہونا» means to run away quickly, as in «چور پولیس کو دیکھ کر نو دو گیارہ ہو گیا».', '{"0": "The idiom is not about counting.", "2": "Living together is not the meaning.", "3": "Cheating is «آنکھوں میں دھول جھونکنا»."}'),
  ('URD-0060', 'Idioms and proverbs', 'Idioms', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Farhang-e-Asifiya (idioms and proverbs)', 'محاورہ «عید کا چاند ہونا» کا مطلب ہے:', '["خوشی منانا", "بہت دنوں بعد نظر آنا", "بہت مشہور ہونا", "بہت خوبصورت ہونا"]', 1, 'The Eid moon is seen once a year, so the idiom means someone seen very rarely.', '{"0": "Rejoicing is «گھی کے چراغ جلانا».", "2": "Fame is not the meaning.", "3": "Beauty is «چاند سا مکھڑا»."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Urdu', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('URD-0061', 'Idioms and proverbs', 'Idioms', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Farhang-e-Asifiya (idioms and proverbs)', 'محاورہ «خون سفید ہونا» کا مطلب ہے:', '["غصہ آنا", "بیمار ہونا", "بے مروت ہو جانا", "ڈر جانا"]', 2, '«خون سفید ہونا» means to lose all feeling for one''s own kin.', '{"0": "Anger is «خون کھولنا».", "1": "The idiom is not about illness.", "3": "Fear is «خون خشک ہونا»."}'),
  ('URD-0062', 'Idioms and proverbs', 'Idioms', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Farhang-e-Asifiya (idioms and proverbs)', 'محاورہ «پانی پانی ہونا» کا مطلب ہے:', '["بہت شرمندہ ہونا", "بہت خوش ہونا", "پسینے میں نہانا", "بہت پیاسا ہونا"]', 0, '«پانی پانی ہونا» means to be so ashamed one wishes to melt away.', '{"1": "Great joy is «باغ باغ ہونا».", "2": "The idiom is not about sweat.", "3": "The idiom is not literal."}'),
  ('URD-0063', 'Idioms and proverbs', 'Idioms', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Farhang-e-Asifiya (idioms and proverbs)', 'محاورہ «لوہے کے چنے چبانا» کا مطلب ہے:', '["بہت مشکل کام کرنا", "کنجوسی کرنا", "بہت بھوکا ہونا", "دانت توڑنا"]', 0, 'Chewing iron grams stands for an extremely hard task.', '{"1": "Miserliness is «دمڑی دمڑی جوڑنا».", "2": "The idiom is not literal.", "3": "Defeating someone is «دانت کھٹے کرنا»."}'),
  ('URD-0064', 'Idioms and proverbs', 'Idioms', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Farhang-e-Asifiya (idioms and proverbs)', 'محاورہ «سبز باغ دکھانا» کا مطلب ہے:', '["سیر کرانا", "جھوٹی امیدیں دلانا", "کھیتی باڑی کرنا", "خوش کرنا"]', 1, '«سبز باغ دکھانا» means to lure someone with promises that will not come true.', '{"0": "The idiom is not literal.", "2": "Farming is not the meaning.", "3": "It is about false hopes, not real happiness."}'),
  ('URD-0065', 'Idioms and proverbs', 'Idioms', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Farhang-e-Asifiya (idioms and proverbs)', 'محاورہ «باغ باغ ہونا» کا مطلب ہے:', '["بہت خوش ہونا", "جھوٹی امید دلانا", "بہت امیر ہونا", "سیر کو جانا"]', 0, '«باغ باغ ہونا» means to be delighted, to bloom with joy.', '{"1": "False hopes are «سبز باغ دکھانا».", "2": "Wealth is not the meaning.", "3": "The idiom is not literal."}'),
  ('URD-0066', 'Idioms and proverbs', 'Idioms', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Farhang-e-Asifiya (idioms and proverbs)', 'محاورہ «ٹیڑھی کھیر» کس کے لیے بولا جاتا ہے؟', '["بے ڈھنگا آدمی", "ضدی بچہ", "مزیدار کھانا", "مشکل کام"]', 3, '«ٹیڑھی کھیر» means a hard nut to crack, as in «یہ کام ٹیڑھی کھیر ہے».', '{"0": "An awkward person is not the meaning.", "1": "The idiom is about a task, not a person.", "2": "The idiom is not about food."}'),
  ('URD-0067', 'Idioms and proverbs', 'Idioms', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Farhang-e-Asifiya (idioms and proverbs)', 'محاورہ «آسمان سر پر اٹھانا» کا مطلب ہے:', '["بہت محنت کرنا", "بہت خوش ہونا", "بہت شور مچانا", "بہت غرور کرنا"]', 2, '«آسمان سر پر اٹھانا» means to raise a great uproar.', '{"0": "Hard work is «خون پسینہ ایک کرنا».", "1": "Joy is «باغ باغ ہونا».", "3": "Pride is «زمین پر پاؤں نہ ٹکنا»."}'),
  ('URD-0068', 'Idioms and proverbs', 'Idioms', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Farhang-e-Asifiya (idioms and proverbs)', 'محاورہ «کان کھڑے ہونا» کا مطلب ہے:', '["بات نہ ماننا", "غصہ آنا", "بہرہ ہو جانا", "چوکنا ہو جانا"]', 3, '«کان کھڑے ہونا» means to become alert, like an animal pricking up its ears.', '{"0": "Not listening is «کان نہ دھرنا».", "1": "Anger is «آگ بگولا ہونا».", "2": "Deafness is the opposite."}'),
  ('URD-0069', 'Idioms and proverbs', 'Idioms', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Farhang-e-Asifiya (idioms and proverbs)', 'جملہ مکمل کیجیے: «امتحان سر پر ہے، اب وہ دن رات ___ ایک کر رہا ہے۔»', '["آنکھ کان", "سر پاؤں", "دال روٹی", "خون پسینہ"]', 3, '«خون پسینہ ایک کرنا» means to work extremely hard.', '{"0": "«آنکھ کان» does not form this idiom.", "1": "«سر پاؤں ایک کرنا» is not an Urdu idiom.", "2": "«دال روٹی» means a simple living."}'),
  ('URD-0070', 'Idioms and proverbs', 'Proverbs', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Farhang-e-Asifiya (idioms and proverbs)', 'کہاوت مکمل کیجیے: «جیسی کرنی ___»', '["ویسی سزا", "ویسی بھرنی", "ویسا پھل", "ویسا انجام"]', 1, '«جیسی کرنی ویسی بھرنی»: as you sow, so shall you reap.', '{"0": "This is not the wording.", "2": "This is not the wording of the proverb.", "3": "This is not the wording."}'),
  ('URD-0071', 'Idioms and proverbs', 'Proverbs', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Farhang-e-Asifiya (idioms and proverbs)', 'کہاوت مکمل کیجیے: «ناچ نہ جانے ___ ٹیڑھا»', '["ڈھول", "آنگن", "رستہ", "گھر"]', 1, '«ناچ نہ جانے آنگن ٹیڑھا»: one who cannot dance blames the floor, i.e. blaming circumstances for one''s own lack of skill.', '{"0": "The proverb names the courtyard, «آنگن».", "2": "The proverb names the courtyard, «آنگن».", "3": "The proverb names the courtyard, «آنگن»."}'),
  ('URD-0072', 'Idioms and proverbs', 'Proverbs', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Farhang-e-Asifiya (idioms and proverbs)', '«جس کی لاٹھی اس کی بھینس» کا مطلب ہے:', '["طاقتور کی بات چلتی ہے", "چرواہا ہوشیار ہوتا ہے", "محنت کا پھل میٹھا ہے", "ہر چیز کا مالک ہوتا ہے"]', 0, '«جس کی لاٹھی اس کی بھینس» means might is right.', '{"1": "The proverb is not literal.", "2": "That is «محنت کا پھل میٹھا ہوتا ہے».", "3": "It is about force, not ownership."}'),
  ('URD-0073', 'Idioms and proverbs', 'Proverbs', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Farhang-e-Asifiya (idioms and proverbs)', '«دور کے ڈھول سہانے» کا مطلب ہے:', '["ڈھول کی آواز دور تک جاتی ہے", "پرانی چیز اچھی ہوتی ہے", "شور سے دور رہنا چاہیے", "دور کی چیز اچھی لگتی ہے"]', 3, 'Drums sound sweet from far away: things look better from a distance than they are.', '{"0": "The proverb is not literal.", "1": "It is about distance, not age.", "2": "That is not the meaning."}'),
  ('URD-0074', 'Idioms and proverbs', 'Proverbs', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Farhang-e-Asifiya (idioms and proverbs)', '«اندھوں میں کانا راجا» کا مطلب ہے:', '["کم علموں میں تھوڑا جاننے والا بھی بڑا سمجھا جاتا ہے", "اندھوں کی مدد کرنی چاہیے", "بادشاہ ہمیشہ کمزور ہوتا ہے", "ظاہری عیب سے بچنا چاہیے"]', 0, 'Among the blind, the one-eyed man is king: a little skill stands out among those who have none.', '{"1": "The proverb is not literal.", "2": "That is not the meaning.", "3": "That is not the meaning."}'),
  ('URD-0075', 'Idioms and proverbs', 'Proverbs', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Farhang-e-Asifiya (idioms and proverbs)', '«ایک انار سو بیمار» کا مطلب ہے:', '["انار صحت کے لیے مفید ہے", "بیمار کو پھل دینا چاہیے", "ایک آدمی سب کا علاج نہیں کر سکتا", "چیز ایک اور چاہنے والے بہت"]', 3, 'One pomegranate and a hundred sick people: one thing and many who want it.', '{"0": "The proverb is not literal.", "1": "That is not the meaning.", "2": "That is not the meaning."}'),
  ('URD-0076', 'Idioms and proverbs', 'Proverbs', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Farhang-e-Asifiya (idioms and proverbs)', '«الٹا چور کوتوال کو ڈانٹے» کس موقع پر بولا جاتا ہے؟', '["جب دو چور آپس میں لڑیں", "جب پولیس چور کو پکڑ لے", "جب کوئی چوری سے توبہ کرے", "جب قصوروار خود بے قصور پر الزام لگائے"]', 3, 'The thief scolding the police officer: the guilty blaming the innocent.', '{"0": "That is not the meaning.", "1": "That is the normal order, not the reversed one in the proverb.", "2": "That is not the meaning."}'),
  ('URD-0077', 'Idioms and proverbs', 'Proverbs', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Farhang-e-Asifiya (idioms and proverbs)', '«گھر کا بھیدی لنکا ڈھائے» کا مطلب ہے:', '["گھر بنانا مشکل کام ہے", "بڑی سلطنتیں بھی ختم ہو جاتی ہیں", "مہمان سے ہوشیار رہنا چاہیے", "گھر کا راز جاننے والا ہی سب سے بڑا نقصان پہنچاتا ہے"]', 3, 'Lanka fell through someone who knew its secrets: the insider who betrays does the most harm.', '{"0": "The proverb is not literal.", "1": "That is not the meaning.", "2": "It is about an insider, not a guest."}'),
  ('URD-0078', 'Idioms and proverbs', 'Proverbs', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Farhang-e-Asifiya (idioms and proverbs)', '«تھوتھا چنا باجے گھنا» کا مطلب ہے:', '["خاموشی بہتر ہے", "کم علم آدمی زیادہ شور کرتا ہے", "چنے سستے ہوتے ہیں", "محنت سے کامیابی ملتی ہے"]', 1, 'A hollow gram rattles loudest: empty vessels make the most noise.', '{"0": "Close in spirit, but the proverb is about the hollow person who talks most.", "2": "The proverb is not literal.", "3": "That is not the meaning."}'),
  ('URD-0079', 'Idioms and proverbs', 'Proverbs', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Farhang-e-Asifiya (idioms and proverbs)', '«بندر کیا جانے ادرک کا سواد» کا مطلب ہے:', '["ناقدرا اچھی چیز کی قدر نہیں جانتا", "جانور کھانا ضائع کرتے ہیں", "ادرک کڑوا ہوتا ہے", "ہر ایک کا ذوق الگ ہوتا ہے"]', 0, 'What does a monkey know of the taste of ginger: a fool cannot value what is good.', '{"1": "That is not the meaning.", "2": "The proverb is not literal.", "3": "Close, but the proverb mocks one who cannot value something good."}'),
  ('URD-0080', 'Idioms and proverbs', 'Proverbs', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Farhang-e-Asifiya (idioms and proverbs)', '«دودھ کا جلا چھاچھ بھی پھونک پھونک کر پیتا ہے» کا مطلب ہے:', '["لالچ بری بلا ہے", "صبر کا پھل میٹھا ہوتا ہے", "گرم دودھ نہیں پینا چاہیے", "ایک بار نقصان اٹھانے والا آئندہ بہت احتیاط کرتا ہے"]', 3, 'Once burnt by milk, one blows even on buttermilk: once bitten, twice shy.', '{"0": "That is a different proverb.", "1": "That is a different proverb.", "2": "The proverb is not literal."}')
) AS s
