INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Urdu', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('URD-0081', 'Idioms and proverbs', 'Proverbs', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Farhang-e-Asifiya (idioms and proverbs)', '«آم کے آم گٹھلیوں کے دام» کا مطلب ہے:', '["محنت کا پھل", "نقصان کا سودا", "دہرا فائدہ", "مہنگا سودا"]', 2, 'You eat the mangoes and still sell the stones: a double benefit.', '{"0": "That is not the meaning.", "1": "It means the opposite: a double gain.", "3": "That is not the meaning."}'),
  ('URD-0082', 'Idioms and proverbs', 'Proverbs', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Feroz-ul-Lughat; Farhang-e-Asifiya (idioms and proverbs)', 'کہاوت مکمل کیجیے: «اب پچھتائے کیا ہوت جب ___ چگ گئیں کھیت»', '["بکریاں", "مرغیاں", "گائیں", "چڑیاں"]', 3, 'Regret is useless once the sparrows have eaten the crop: it is too late after the damage is done.', '{"0": "The proverb names birds, «چڑیاں».", "1": "The proverb names «چڑیاں», the sparrows.", "2": "The proverb names birds, «چڑیاں»."}'),
  ('URD-0083', 'Grammar', 'Parts of speech', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Maulvi Abdul Haq, Qawaid-e-Urdu', 'اردو قواعد میں کلمہ کی کتنی قسمیں ہیں؟', '["پانچ", "دو", "چار", "تین"]', 3, 'A word (کلمہ) is of three kinds: «اسم» (noun), «فعل» (verb) and «حرف» (particle).', '{"0": "There are three: «اسم، فعل، حرف».", "1": "There are three, not two.", "2": "There are three: «اسم، فعل، حرف»."}'),
  ('URD-0084', 'Grammar', 'Nouns', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Maulvi Abdul Haq, Qawaid-e-Urdu', '«لاہور» کون سا اسم ہے؟', '["اسمِ نکرہ", "اسمِ ضمیر", "اسمِ صفت", "اسمِ معرفہ"]', 3, '«لاہور» names one particular place, so it is «اسمِ معرفہ» (proper noun); «شہر» would be «اسمِ نکرہ».', '{"0": "«اسمِ نکرہ» is a common noun like «شہر»; «لاہور» names one particular city.", "1": "«اسمِ ضمیر» is a pronoun like «وہ».", "2": "«اسمِ صفت» is an adjective."}'),
  ('URD-0085', 'Grammar', 'Nouns', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Maulvi Abdul Haq, Qawaid-e-Urdu', '«شہر» کون سا اسم ہے؟', '["اسمِ معرفہ", "اسمِ آلہ", "اسمِ نکرہ", "اسمِ ظرف"]', 2, '«شہر» is any city, so it is «اسمِ نکرہ» (common noun).', '{"0": "«اسمِ معرفہ» names one particular thing, like «کراچی».", "1": "«اسمِ آلہ» names a tool, like «قلم».", "3": "«اسمِ ظرف» names a time or place by its use, like «مسجد» or «صبح»."}'),
  ('URD-0086', 'Grammar', 'Nouns', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Maulvi Abdul Haq, Qawaid-e-Urdu', '«قلم» اور «تلوار» کس قسم کے اسم ہیں؟', '["اسمِ ظرف", "اسمِ تصغیر", "اسمِ جمع", "اسمِ آلہ"]', 3, '«اسمِ آلہ» is the name of a tool or instrument used to do work: «قلم»، «تلوار»، «قینچی».', '{"0": "«اسمِ ظرف» names a time or place.", "1": "«اسمِ تصغیر» is a diminutive, like «پہاڑی».", "2": "«اسمِ جمع» names a group, like «فوج»."}'),
  ('URD-0087', 'Grammar', 'Nouns', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Maulvi Abdul Haq, Qawaid-e-Urdu', '«مسجد» کس قسم کا اسم ہے؟', '["اسمِ آلہ", "اسمِ ظرفِ مکان", "اسمِ صفت", "اسمِ ظرفِ زمان"]', 1, '«مسجد» means the place of prostration, so it is «اسمِ ظرفِ مکان» (noun of place).', '{"0": "«اسمِ آلہ» names a tool.", "2": "«اسمِ صفت» is an adjective.", "3": "«ظرفِ زمان» names a time, like «صبح» or «شام»."}'),
  ('URD-0088', 'Grammar', 'Nouns', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Maulvi Abdul Haq, Qawaid-e-Urdu', '«فوج» اور «جماعت» کس قسم کے اسم ہیں؟', '["اسمِ ضمیر", "اسمِ جمع", "اسمِ تصغیر", "اسمِ آلہ"]', 1, '«اسمِ جمع» is singular in form but names a group: «فوج»، «جماعت»، «قافلہ».', '{"0": "«اسمِ ضمیر» is a pronoun.", "2": "«اسمِ تصغیر» is a diminutive.", "3": "«اسمِ آلہ» names a tool."}'),
  ('URD-0089', 'Grammar', 'Nouns', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Maulvi Abdul Haq, Qawaid-e-Urdu', '«پہاڑی» (چھوٹا پہاڑ) کس قسم کا اسم ہے؟', '["اسمِ مصدر", "اسمِ تکبیر", "اسمِ تصغیر", "اسمِ فاعل"]', 2, '«اسمِ تصغیر» names a smaller form of a thing: «پہاڑی» from «پہاڑ»، «ڈبیا» from «ڈبا».', '{"0": "«مصدر» is the infinitive, like «لکھنا».", "1": "«اسمِ تکبیر» makes a thing bigger, like «پگڑ» from «پگڑی».", "3": "«اسمِ فاعل» names the doer, like «لکھنے والا»."}'),
  ('URD-0090', 'Grammar', 'Pronouns and adjectives', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Maulvi Abdul Haq, Qawaid-e-Urdu', 'جملہ «وہ کل آئے گا» میں «وہ» کیا ہے؟', '["حرف", "ضمیر", "فعل", "صفت"]', 1, '«وہ» stands in place of a noun, so it is «ضمیر» (pronoun).', '{"0": "«حرف» is a particle like «سے» or «کو».", "2": "The verb is «آئے گا».", "3": "«صفت» describes a noun, like «اچھا»."}'),
  ('URD-0091', 'Grammar', 'Pronouns and adjectives', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Maulvi Abdul Haq, Qawaid-e-Urdu', '«اچھا لڑکا» میں «اچھا» کیا ہے؟', '["موصوف", "صفت", "ضمیر", "فعل"]', 1, '«اچھا» tells a quality of «لڑکا», so it is «صفت» and «لڑکا» is «موصوف».', '{"0": "«موصوف» is the noun being described, «لڑکا».", "2": "«ضمیر» is a pronoun.", "3": "There is no verb in this phrase."}'),
  ('URD-0092', 'Grammar', 'Verbs', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Maulvi Abdul Haq, Qawaid-e-Urdu', 'مصدر کی علامت کیا ہے؟', '["نا", "کا", "نے", "گا"]', 0, 'Every Urdu infinitive (مصدر) ends in «نا»: «لکھنا»، «پڑھنا»، «کھانا».', '{"1": "«کا» marks possession (اضافت).", "2": "«نے» marks the doer (فاعل).", "3": "«گا» marks the future tense, as in «لکھے گا»."}'),
  ('URD-0093', 'Grammar', 'Verbs', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Maulvi Abdul Haq, Qawaid-e-Urdu', 'جملہ «اس نے خط لکھا» کس زمانے میں ہے؟', '["حال", "امر", "مستقبل", "ماضی"]', 3, '«لکھا» shows an action already done, so the sentence is in the past tense (ماضی مطلق).', '{"0": "The present would be «وہ خط لکھتا ہے» or «لکھ رہا ہے».", "1": "A command would be «خط لکھو».", "2": "The future would be «وہ خط لکھے گا»."}'),
  ('URD-0094', 'Grammar', 'Verbs', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Maulvi Abdul Haq, Qawaid-e-Urdu', 'جملہ «احمد کل لاہور جائے گا» کس زمانے میں ہے؟', '["مستقبل", "حال", "ماضی استمراری", "ماضی"]', 0, '«جائے گا» shows an action still to come, so it is the future tense (مستقبل).', '{"1": "The present would be «احمد لاہور جا رہا ہے».", "2": "That would be «احمد لاہور جاتا تھا».", "3": "The past would be «احمد لاہور گیا»."}'),
  ('URD-0095', 'Grammar', 'Sentence', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Maulvi Abdul Haq, Qawaid-e-Urdu', 'جملہ «احمد نے سیب کھایا» میں فاعل کون ہے؟', '["احمد", "سیب", "نے", "کھایا"]', 0, 'The doer of the action is «احمد», so it is «فاعل»; «نے» is the sign of the فاعل.', '{"1": "«سیب» is the thing eaten, the object (مفعول).", "2": "«نے» is the sign of the doer, not the doer itself.", "3": "«کھایا» is the verb (فعل)."}'),
  ('URD-0096', 'Grammar', 'Sentence', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Maulvi Abdul Haq, Qawaid-e-Urdu', 'جملہ «احمد نے سیب کھایا» میں مفعول کون ہے؟', '["احمد", "نے", "سیب", "کھایا"]', 2, 'The action falls on «سیب», so it is «مفعول» (object).', '{"0": "«احمد» is the doer (فاعل).", "1": "«نے» is the sign of the doer.", "3": "«کھایا» is the verb (فعل)."}'),
  ('URD-0097', 'Grammar', 'Particles', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Maulvi Abdul Haq, Qawaid-e-Urdu', '«کا، کی، کے» کس کی علامت ہیں؟', '["مفعول", "فاعل", "اضافت", "مستقبل"]', 2, '«کا، کی، کے» link one noun to another to show possession or relation; they are the signs of «اضافت».', '{"0": "The sign of the object is «کو».", "1": "The sign of the doer is «نے».", "3": "The future is marked by «گا، گی، گے»."}'),
  ('URD-0098', 'Grammar', 'Particles', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Maulvi Abdul Haq, Qawaid-e-Urdu', '«سے، کو، میں، پر» کس قسم کے حروف ہیں؟', '["حروفِ جار", "حروفِ عطف", "حروفِ تشبیہ", "حروفِ ندا"]', 0, '«سے، کو، میں، پر» link a noun to the verb and show place, direction and so on; they are «حروفِ جار».', '{"1": "«حروفِ عطف» join words, like «اور» or «یا».", "2": "«حروفِ تشبیہ» compare, like «جیسا» or «مانند».", "3": "«حروفِ ندا» call someone, like «اے»."}'),
  ('URD-0099', 'Grammar', 'Particles', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Maulvi Abdul Haq, Qawaid-e-Urdu', '«اور» اور «یا» کس قسم کے حروف ہیں؟', '["حروفِ عطف", "حروفِ ندا", "حروفِ جار", "حروفِ تاکید"]', 0, '«اور» (and) and «یا» (or) join two words or sentences, so they are «حروفِ عطف».', '{"1": "«حروفِ ندا» are calling words like «اے».", "2": "«حروفِ جار» are «سے، کو، میں، پر».", "3": "«حروفِ تاکید» add stress, like «ہی» or «بھی»."}'),
  ('URD-0100', 'Grammar', 'Singular and plural', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Maulvi Abdul Haq, Qawaid-e-Urdu', '«کتاب» کی جمع کیا ہے؟', '["کتابت", "کاتب", "مکتب", "کتب"]', 3, 'The Arabic plural of «کتاب» is «کتب»; «کتابیں» is the Urdu plural.', '{"0": "«کتابت» means writing or calligraphy.", "1": "«کاتب» is a scribe.", "2": "«مکتب» is a school."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Urdu', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('URD-0101', 'Grammar', 'Singular and plural', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Maulvi Abdul Haq, Qawaid-e-Urdu', '«شاعر» کی جمع کیا ہے؟', '["مشاعرہ", "شعرا", "اشعار", "شعور"]', 1, 'The plural of «شاعر» is «شعرا»; «اشعار» is the plural of «شعر».', '{"0": "«مشاعرہ» is a poetry gathering.", "2": "«اشعار» is the plural of «شعر» (a verse).", "3": "«شعور» means awareness."}'),
  ('URD-0102', 'Grammar', 'Singular and plural', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Maulvi Abdul Haq, Qawaid-e-Urdu', '«ملک» کی جمع کیا ہے؟', '["ملکیت", "ممالک", "املاک", "ملوک"]', 1, 'The plural of «مُلک» (country) is «ممالک».', '{"0": "«ملکیت» means ownership.", "2": "«املاک» is the plural of «مِلک» (property).", "3": "«ملوک» is the plural of «مَلِک» (king)."}'),
  ('URD-0103', 'Grammar', 'Singular and plural', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Maulvi Abdul Haq, Qawaid-e-Urdu', '«قاعدہ» کی جمع کیا ہے؟', '["قعود", "قاعدے", "مقاعد", "قواعد"]', 3, 'The Arabic plural of «قاعدہ» is «قواعد», as in «قواعدِ اردو».', '{"0": "«قعود» means sitting.", "1": "«قاعدے» is the Urdu oblique plural, not the Arabic plural asked for in grammar tests.", "2": "«مقاعد» is not the plural of «قاعدہ»."}'),
  ('URD-0104', 'Grammar', 'Singular and plural', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Maulvi Abdul Haq, Qawaid-e-Urdu', '«شے» کی جمع کیا ہے؟', '["شیوخ", "اشعار", "شیئیں", "اشیا"]', 3, 'The plural of «شے» (thing) is «اشیا», as in «اشیائے خورونوش».', '{"0": "«شیوخ» is the plural of «شیخ».", "1": "«اشعار» is the plural of «شعر».", "2": "This is not a standard plural."}'),
  ('URD-0105', 'Grammar', 'Singular and plural', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Maulvi Abdul Haq, Qawaid-e-Urdu', '«حقوق» کا واحد کیا ہے؟', '["حقیر", "حقیقت", "محقق", "حق"]', 3, '«حقوق» is the plural of «حق» (a right), as in «حقوق العباد».', '{"0": "«حقیر» means lowly.", "1": "The plural of «حقیقت» is «حقائق».", "2": "«محقق» is a researcher."}'),
  ('URD-0106', 'Grammar', 'Singular and plural', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Maulvi Abdul Haq, Qawaid-e-Urdu', '«اولیا» کا واحد کیا ہے؟', '["اولاد", "ولی", "ولادت", "والی"]', 1, '«اولیا» is the plural of «ولی» (a saint or friend of God).', '{"0": "«اولاد» means children.", "2": "«ولادت» means birth.", "3": "«والی» is a ruler; its plural is «ولاۃ»."}'),
  ('URD-0107', 'Grammar', 'Singular and plural', 'hard', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Maulvi Abdul Haq, Qawaid-e-Urdu', '«جزائر» کا واحد کیا ہے؟', '["جزیرہ", "جزیہ", "جزا", "جز"]', 0, '«جزائر» is the plural of «جزیرہ» (island); «الجزائر» means the islands.', '{"1": "«جزیہ» is a tax.", "2": "The plural of «جزا» is not «جزائر».", "3": "The plural of «جز» (part) is «اجزا»."}'),
  ('URD-0108', 'Grammar', 'Gender', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Maulvi Abdul Haq, Qawaid-e-Urdu', '«شیر» کا مؤنث کیا ہے؟', '["شیرن", "شیری", "شیرنی", "شیرا"]', 2, 'The feminine of «شیر» is «شیرنی».', '{"0": "This is not the standard form.", "1": "This is not the standard form.", "3": "This is not a feminine form."}'),
  ('URD-0109', 'Grammar', 'Gender', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Maulvi Abdul Haq, Qawaid-e-Urdu', '«بیل» کا مؤنث کیا ہے؟', '["بیلنی", "بھینس", "گائے", "بچھیا"]', 2, '«بیل» (ox) and «گائے» (cow) are a pair whose feminine is a different word.', '{"0": "There is no such word.", "1": "The male of «بھینس» is «بھینسا».", "3": "«بچھیا» is a young cow (heifer)."}'),
  ('URD-0110', 'Grammar', 'Gender', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Maulvi Abdul Haq, Qawaid-e-Urdu', '«بادشاہ» کا مؤنث کیا ہے؟', '["شہزادی", "بادشاہی", "رانی", "ملکہ"]', 3, 'The feminine of «بادشاہ» is «ملکہ».', '{"0": "«شہزادی» is the feminine of «شہزادہ» (prince).", "1": "«بادشاہی» means kingship.", "2": "«رانی» is the feminine of «راجا»."}'),
  ('URD-0111', 'Grammar', 'Gender', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Maulvi Abdul Haq, Qawaid-e-Urdu', '«ماموں» کا مؤنث کیا ہے؟', '["چچی", "پھوپھی", "خالہ", "ممانی"]', 3, '«ماموں» (mother''s brother) and his wife «ممانی» are the gender pair.', '{"0": "«چچی» is the feminine of «چچا».", "1": "«پھوپھی» is the father''s sister.", "2": "«خالہ» is the mother''s sister; her husband is «خالو»."}'),
  ('URD-0112', 'Grammar', 'Gender', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Maulvi Abdul Haq, Qawaid-e-Urdu', '«دھوبی» کا مؤنث کیا ہے؟', '["دھوبن", "دھوبیا", "دھلائی", "دھوبنی"]', 0, 'The feminine of «دھوبی» is «دھوبن».', '{"1": "This is not a feminine form.", "2": "«دھلائی» means washing.", "3": "The standard form is «دھوبن»."}'),
  ('URD-0113', 'Grammar', 'Gender', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Maulvi Abdul Haq, Qawaid-e-Urdu', 'ان میں سے کون سا لفظ مؤنث ہے؟', '["قلم", "دروازہ", "پانی", "کتاب"]', 3, '«کتاب» is feminine: «کتاب اچھی ہے».', '{"0": "«قلم» is masculine: «قلم اچھا ہے».", "1": "«دروازہ» is masculine.", "2": "«پانی» is masculine: «پانی ٹھنڈا ہے»."}'),
  ('URD-0114', 'Grammar', 'Gender', 'hard', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Maulvi Abdul Haq, Qawaid-e-Urdu', 'ان میں سے کون سا لفظ مذکر ہے؟', '["ہوا", "کتاب", "دہی", "عینک"]', 2, '«دہی» is masculine in standard Urdu: «دہی کھٹا ہے», though it ends in «ی».', '{"0": "«ہوا» is feminine: «ٹھنڈی ہوا».", "1": "«کتاب» is feminine.", "3": "«عینک» is feminine: «عینک ٹوٹ گئی»."}'),
  ('URD-0115', 'Grammar', 'Sentence', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Maulvi Abdul Haq, Qawaid-e-Urdu', 'ان میں سے کون سا جملہ درست ہے؟', '["مجھ نے کتاب پڑھی", "میں نے کتاب پڑھی", "میں کتاب پڑھی", "میں نے کتاب پڑھا"]', 1, 'With «نے», the past verb agrees with the object; «کتاب» is feminine, so «میں نے کتاب پڑھی» is correct.', '{"0": "The form with «نے» is «میں نے», not «مجھ نے».", "2": "With a past transitive verb the doer takes «نے».", "3": "«کتاب» is feminine, so the verb must be «پڑھی»."}'),
  ('URD-0116', 'Grammar', 'Sentence', 'hard', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Maulvi Abdul Haq, Qawaid-e-Urdu', 'جمع مفعول کے ساتھ کون سا جملہ درست ہے؟', '["ہم کئی کتابیں پڑھیں", "ہم نے کئی کتابیں پڑھے", "ہم نے کئی کتابیں پڑھیں", "ہم نے کئی کتابیں پڑھا"]', 2, 'With «نے», the verb agrees with the object «کتابیں» (feminine plural), so it is «پڑھیں».', '{"0": "With a past transitive verb the doer takes «نے».", "1": "«پڑھے» is masculine plural; «کتابیں» is feminine.", "3": "The verb must agree with feminine plural «کتابیں»."}'),
  ('URD-0117', 'Poets and writers', 'Iqbal', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Ram Babu Saksena, Tareekh-e-Adab-e-Urdu; Jameel Jalibi, Tareekh-e-Adab-e-Urdu', '«بانگِ درا» کس کا مجموعۂ کلام ہے؟', '["الطاف حسین حالی", "مرزا غالب", "علامہ محمد اقبال", "فیض احمد فیض"]', 2, '«بانگِ درا» (1924) was Iqbal''s first Urdu collection.', '{"0": "Hali''s best-known poem is «مسدسِ حالی».", "1": "Ghalib''s Urdu poetry is in «دیوانِ غالب».", "3": "Faiz''s first collection is «نقشِ فریادی»."}'),
  ('URD-0118', 'Poets and writers', 'Iqbal', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Ram Babu Saksena, Tareekh-e-Adab-e-Urdu; Jameel Jalibi, Tareekh-e-Adab-e-Urdu', 'نظمیں «شکوہ» اور «جوابِ شکوہ» کس نے لکھیں؟', '["حفیظ جالندھری", "اکبر الٰہ آبادی", "علامہ محمد اقبال", "مولانا ظفر علی خان"]', 2, 'Iqbal wrote «شکوہ» and its answer «جوابِ شکوہ»; both are in «بانگِ درا».', '{"0": "Hafeez wrote «شاہنامۂ اسلام».", "1": "Akbar is known for humour and satire.", "3": "Zafar Ali Khan edited «زمیندار»."}'),
  ('URD-0119', 'Poets and writers', 'Iqbal', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Ram Babu Saksena, Tareekh-e-Adab-e-Urdu; Jameel Jalibi, Tareekh-e-Adab-e-Urdu', 'ان میں سے کون سا مجموعہ علامہ اقبال کا نہیں ہے؟', '["بالِ جبریل", "نقشِ فریادی", "ضربِ کلیم", "ارمغانِ حجاز"]', 1, '«نقشِ فریادی» is Faiz Ahmed Faiz''s first collection; the other three are Iqbal''s.', '{"0": "«بالِ جبریل» (1935) is by Iqbal.", "2": "«ضربِ کلیم» (1936) is by Iqbal.", "3": "«ارمغانِ حجاز» (1938) is by Iqbal."}'),
  ('URD-0120', 'Poets and writers', 'Iqbal', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Ram Babu Saksena, Tareekh-e-Adab-e-Urdu; Jameel Jalibi, Tareekh-e-Adab-e-Urdu', '«شاعرِ مشرق» کس کا لقب ہے؟', '["علامہ محمد اقبال", "جوش ملیح آبادی", "میر تقی میر", "نظیر اکبر آبادی"]', 0, 'Iqbal is called «شاعرِ مشرق» (Poet of the East) and «حکیم الامت».', '{"1": "Josh is called «شاعرِ انقلاب».", "2": "Mir is called «خدائے سخن».", "3": "Nazeer is called «عوامی شاعر»."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Urdu', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('URD-0121', 'Poets and writers', 'Classical poets', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Ram Babu Saksena, Tareekh-e-Adab-e-Urdu; Jameel Jalibi, Tareekh-e-Adab-e-Urdu', '«خدائے سخن» کس شاعر کو کہا جاتا ہے؟', '["میر تقی میر", "علامہ اقبال", "داغ دہلوی", "مرزا غالب"]', 0, 'Mir Taqi Mir is called «خدائے سخن» (god of poetry) for his ghazal.', '{"1": "Iqbal is «شاعرِ مشرق».", "2": "Daagh is famous as a teacher of many poets.", "3": "Ghalib has the title «نجم الدولہ»."}'),
  ('URD-0122', 'Poets and writers', 'Classical poets', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Ram Babu Saksena, Tareekh-e-Adab-e-Urdu; Jameel Jalibi, Tareekh-e-Adab-e-Urdu', 'مرزا غالب کا اصل نام کیا تھا؟', '["محمد تقی", "مرزا اسد اللہ خان", "مرزا محمد رفیع", "ابراہیم ذوق"]', 1, 'Ghalib''s name was Mirza Asadullah Khan; he first wrote under the pen name «اسد».', '{"0": "That is the name of Mir.", "2": "That is the name of Sauda.", "3": "Zauq was Ghalib''s rival at the Mughal court."}'),
  ('URD-0123', 'Poets and writers', 'Classical poets', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Ram Babu Saksena, Tareekh-e-Adab-e-Urdu; Jameel Jalibi, Tareekh-e-Adab-e-Urdu', 'غالب کے خطوط کے مجموعے کون سے ہیں؟', '["آبِ حیات اور نیرنگِ خیال", "بانگِ درا اور بالِ جبریل", "باغ و بہار اور فسانۂ عجائب", "عودِ ہندی اور اردوئے معلیٰ"]', 3, 'Ghalib''s Urdu letters were collected as «عودِ ہندی» (1868) and «اردوئے معلیٰ» (1869).', '{"0": "These are by Muhammad Hussain Azad.", "1": "These are Iqbal''s collections.", "2": "These are dastans by Mir Amman and Suroor."}'),
  ('URD-0124', 'Poets and writers', 'Classical poets', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Ram Babu Saksena, Tareekh-e-Adab-e-Urdu; Jameel Jalibi, Tareekh-e-Adab-e-Urdu', 'اردو کے پہلے صاحبِ دیوان شاعر کون مانے جاتے ہیں؟', '["ولی دکنی", "میر تقی میر", "امیر خسرو", "محمد قلی قطب شاہ"]', 3, 'Muhammad Quli Qutb Shah (died 1611), ruler of Golconda, is counted as the first Urdu poet with a diwan.', '{"0": "Wali brought Urdu ghazal to Delhi, but Quli Qutb Shah''s diwan came first.", "1": "Mir came more than a century later.", "2": "Khusrau wrote in Persian and Hindvi; no Urdu diwan of his exists."}'),
  ('URD-0125', 'Poets and writers', 'Classical poets', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Ram Babu Saksena, Tareekh-e-Adab-e-Urdu; Jameel Jalibi, Tareekh-e-Adab-e-Urdu', 'میر انیس اور مرزا دبیر کس صنفِ سخن کے لیے مشہور ہیں؟', '["مرثیہ", "رباعی", "غزل", "قصیدہ"]', 0, 'Mir Anees and Mirza Dabeer of Lucknow are the two masters of the Urdu marsiya.', '{"1": "Anees wrote rubais too, but both are famous for marsiya.", "2": "The great ghazal poets are Mir and Ghalib.", "3": "The master of qasida is Sauda."}'),
  ('URD-0126', 'Poets and writers', 'Classical poets', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Ram Babu Saksena, Tareekh-e-Adab-e-Urdu; Jameel Jalibi, Tareekh-e-Adab-e-Urdu', '«عوامی شاعر» کس شاعر کو کہا جاتا ہے؟', '["نظیر اکبر آبادی", "سودا", "میر درد", "مومن خان مومن"]', 0, 'Nazeer Akbarabadi wrote about fairs, seasons and common life, so he is called the poet of the people.', '{"1": "Sauda is known for qasida and satire.", "2": "Khwaja Mir Dard is known as a Sufi poet.", "3": "Momin is known for the ghazal."}'),
  ('URD-0127', 'Poets and writers', 'Classical poets', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Ram Babu Saksena, Tareekh-e-Adab-e-Urdu; Jameel Jalibi, Tareekh-e-Adab-e-Urdu', 'داغ دہلوی سے اصلاح لینے والے مشہور شاعر کون تھے؟', '["علامہ محمد اقبال", "میر تقی میر", "مرزا غالب", "فیض احمد فیض"]', 0, 'As a young poet Iqbal sent his ghazals to Daagh Dehlvi for correction by post.', '{"1": "Mir lived a century before Daagh.", "2": "Ghalib was older than Daagh.", "3": "Faiz was born after Daagh died in 1905."}'),
  ('URD-0128', 'Poets and writers', 'Classical poets', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Ram Babu Saksena, Tareekh-e-Adab-e-Urdu; Jameel Jalibi, Tareekh-e-Adab-e-Urdu', 'اکبر الٰہ آبادی کس رنگ کی شاعری کے لیے مشہور ہیں؟', '["طنز و مزاح", "رومانوی شاعری", "انقلابی شاعری", "مرثیہ"]', 0, 'Akbar Allahabadi used humour and satire to mock blind imitation of Western ways.', '{"1": "Akbar is known for satire, not romance.", "2": "Revolutionary poetry is Josh''s field.", "3": "Marsiya is the field of Anees and Dabeer."}'),
  ('URD-0129', 'Poets and writers', 'Hali and Sir Syed', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Ram Babu Saksena, Tareekh-e-Adab-e-Urdu; Jameel Jalibi, Tareekh-e-Adab-e-Urdu', '«مسدسِ مد و جزرِ اسلام» کس نے لکھی؟', '["ڈپٹی نذیر احمد", "علامہ شبلی نعمانی", "سر سید احمد خان", "مولانا الطاف حسین حالی"]', 3, 'Hali wrote the Musaddas (1879), known as «مسدسِ حالی», at Sir Syed''s urging.', '{"0": "Nazir Ahmad wrote novels like «مراۃ العروس».", "1": "Shibli wrote «سیرت النبی» and «الفاروق».", "2": "Sir Syed asked Hali to write it, but did not write it."}'),
  ('URD-0130', 'Poets and writers', 'Hali and Sir Syed', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Ram Babu Saksena, Tareekh-e-Adab-e-Urdu; Jameel Jalibi, Tareekh-e-Adab-e-Urdu', '«مقدمۂ شعر و شاعری» کس کی تصنیف ہے؟', '["محمد حسین آزاد", "علامہ شبلی نعمانی", "مولانا الطاف حسین حالی", "مولوی عبدالحق"]', 2, 'Hali''s «مقدمۂ شعر و شاعری» (1893) is the first major book of Urdu literary criticism.', '{"0": "Azad wrote «آبِ حیات».", "1": "Shibli wrote «شعر العجم».", "3": "Abdul Haq wrote «قواعدِ اردو»."}'),
  ('URD-0131', 'Poets and writers', 'Hali and Sir Syed', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Ram Babu Saksena, Tareekh-e-Adab-e-Urdu; Jameel Jalibi, Tareekh-e-Adab-e-Urdu', '«حیاتِ جاوید» کس کی سوانح عمری ہے؟', '["مرزا غالب", "شیخ سعدی", "سر سید احمد خان", "علامہ اقبال"]', 2, 'Hali wrote «حیاتِ جاوید» (1901), the life of Sir Syed Ahmad Khan.', '{"0": "Hali''s biography of Ghalib is «یادگارِ غالب».", "1": "Hali''s book on Saadi is «حیاتِ سعدی».", "3": "Hali died in 1914, long before Iqbal''s life was complete."}'),
  ('URD-0132', 'Poets and writers', 'Hali and Sir Syed', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Ram Babu Saksena, Tareekh-e-Adab-e-Urdu; Jameel Jalibi, Tareekh-e-Adab-e-Urdu', 'رسالہ «تہذیب الاخلاق» کس نے جاری کیا؟', '["مولانا ظفر علی خان", "سر سید احمد خان", "مولانا محمد علی جوہر", "مولانا ابو الکلام آزاد"]', 1, 'Sir Syed started «تہذیب الاخلاق» in 1870 to reform Muslim society.', '{"0": "Zafar Ali Khan edited «زمیندار».", "2": "Jauhar edited «کامریڈ» and «ہمدرد».", "3": "Azad edited «الہلال»."}'),
  ('URD-0133', 'Poets and writers', 'Prose', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Ram Babu Saksena, Tareekh-e-Adab-e-Urdu; Jameel Jalibi, Tareekh-e-Adab-e-Urdu', '«باغ و بہار» کس کی تصنیف ہے؟', '["رجب علی بیگ سرور", "میر امن دہلوی", "ڈپٹی نذیر احمد", "مرزا ہادی رسوا"]', 1, 'Mir Amman wrote «باغ و بہار» (1802) at Fort William College in simple Urdu prose.', '{"0": "Suroor wrote «فسانۂ عجائب».", "2": "Nazir Ahmad wrote «مراۃ العروس».", "3": "Ruswa wrote «امراؤ جان ادا»."}'),
  ('URD-0134', 'Poets and writers', 'Prose', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Ram Babu Saksena, Tareekh-e-Adab-e-Urdu; Jameel Jalibi, Tareekh-e-Adab-e-Urdu', '«فسانۂ عجائب» کس نے لکھی؟', '["رتن ناتھ سرشار", "رجب علی بیگ سرور", "محمد حسین آزاد", "میر امن دہلوی"]', 1, 'Rajab Ali Beg Suroor of Lucknow wrote «فسانۂ عجائب» in ornate rhymed prose.', '{"0": "Sarshar wrote «فسانۂ آزاد».", "2": "Azad wrote «آبِ حیات».", "3": "Mir Amman wrote «باغ و بہار»."}'),
  ('URD-0135', 'Poets and writers', 'Prose', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Ram Babu Saksena, Tareekh-e-Adab-e-Urdu; Jameel Jalibi, Tareekh-e-Adab-e-Urdu', 'ناول «مراۃ العروس» کس نے لکھا؟', '["ڈپٹی نذیر احمد", "عبدالحلیم شرر", "منشی پریم چند", "مرزا ہادی رسوا"]', 0, 'Deputy Nazir Ahmad wrote «مراۃ العروس» (1869), often counted as the first Urdu novel.', '{"1": "Sharar wrote historical novels like «فردوسِ بریں».", "2": "Premchand wrote «گئودان».", "3": "Ruswa wrote «امراؤ جان ادا»."}'),
  ('URD-0136', 'Poets and writers', 'Prose', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Ram Babu Saksena, Tareekh-e-Adab-e-Urdu; Jameel Jalibi, Tareekh-e-Adab-e-Urdu', 'ناول «امراؤ جان ادا» کس نے لکھا؟', '["ڈپٹی نذیر احمد", "مرزا ہادی رسوا", "سعادت حسن منٹو", "قرۃ العین حیدر"]', 1, 'Mirza Hadi Ruswa wrote «امراؤ جان ادا» (1899), set in Lucknow.', '{"0": "Nazir Ahmad wrote «مراۃ العروس».", "2": "Manto wrote short stories.", "3": "Hyder wrote «آگ کا دریا»."}'),
  ('URD-0137', 'Poets and writers', 'Prose', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Ram Babu Saksena, Tareekh-e-Adab-e-Urdu; Jameel Jalibi, Tareekh-e-Adab-e-Urdu', '«آبِ حیات» کس کی تصنیف ہے؟', '["الطاف حسین حالی", "محمد حسین آزاد", "سر سید احمد خان", "علامہ شبلی نعمانی"]', 1, 'Muhammad Hussain Azad''s «آبِ حیات» (1880) is a history of Urdu poetry and poets.', '{"0": "Hali wrote «مقدمۂ شعر و شاعری».", "2": "Sir Syed wrote «آثار الصنادید».", "3": "Shibli wrote «شعر العجم»."}'),
  ('URD-0138', 'Poets and writers', 'Prose', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Ram Babu Saksena, Tareekh-e-Adab-e-Urdu; Jameel Jalibi, Tareekh-e-Adab-e-Urdu', '«سیرت النبی» کا آغاز کس نے کیا؟', '["سید سلیمان ندوی", "ڈپٹی نذیر احمد", "مولانا حالی", "علامہ شبلی نعمانی"]', 3, 'Shibli Nomani began «سیرت النبی» and his student Syed Sulaiman Nadvi completed it.', '{"0": "Sulaiman Nadvi completed it after Shibli''s death.", "1": "Nazir Ahmad wrote novels.", "2": "Hali wrote «حیاتِ جاوید»."}'),
  ('URD-0139', 'Poets and writers', 'Modern writers', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Ram Babu Saksena, Tareekh-e-Adab-e-Urdu; Jameel Jalibi, Tareekh-e-Adab-e-Urdu', 'افسانہ «ٹوبہ ٹیک سنگھ» کس نے لکھا؟', '["سعادت حسن منٹو", "کرشن چندر", "اشفاق احمد", "منشی پریم چند"]', 0, 'Manto''s «ٹوبہ ٹیک سنگھ» is set in a mental asylum at the time of Partition.', '{"1": "Krishan Chander wrote «ان داتا».", "2": "Ashfaq Ahmed wrote «گڈریا».", "3": "Premchand wrote «کفن»."}'),
  ('URD-0140', 'Poets and writers', 'Modern writers', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Urdu. Checked against: Ram Babu Saksena, Tareekh-e-Adab-e-Urdu; Jameel Jalibi, Tareekh-e-Adab-e-Urdu', 'افسانہ «کفن» کس نے لکھا؟', '["غلام عباس", "راجندر سنگھ بیدی", "سعادت حسن منٹو", "منشی پریم چند"]', 3, 'Premchand''s «کفن» (1936) is among the best-known Urdu short stories.', '{"0": "Ghulam Abbas wrote «آنندی».", "1": "Bedi wrote «لاجونتی».", "2": "Manto wrote «ٹوبہ ٹیک سنگھ»."}')
) AS s
